    GetStaticMapRequest.add_member(:padding, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'Padding', traits: {"smithy.api#documentation" => "<p>Applies additional space (in pixels) around overlay feature to prevent them from being\n         cut or obscured.</p>\n         <note>\n            <p>Value for max and min is determined by:</p>\n            <p>Min: <code>1</code>\n            </p>\n            <p>Max: <code>min(height, width)/4</code>\n            </p>\n         </note>\n         <p>Example: <code>100</code>\n         </p>", "smithy.api#httpQuery" => "padding"}))
    GetStaticMapRequest.add_member(:political_view, Smithy::Schema::Shapes::ShapeRef.new(shape: CountryCode, location_name: 'PoliticalView', traits: {"smithy.api#documentation" => "<p>Specifies the political view, using ISO 3166-2 or ISO 3166-3 country code format.</p>\n         <p>The following political views are currently supported:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ARG</code>: Argentina's view on the Southern Patagonian Ice Field and Tierra\n               Del Fuego, including the Falkland Islands, South Georgia, and South Sandwich\n               Islands</p>\n            </li>\n            <li>\n               <p>\n                  <code>EGY</code>: Egypt's view on Bir Tawil</p>\n            </li>\n            <li>\n               <p>\n                  <code>IND</code>: India's view on Gilgit-Baltistan</p>\n            </li>\n            <li>\n               <p>\n                  <code>KEN</code>: Kenya's view on the Ilemi Triangle</p>\n            </li>\n            <li>\n               <p>\n                  <code>MAR</code>: Morocco's view on Western Sahara</p>\n            </li>\n            <li>\n               <p>\n                  <code>RUS</code>: Russia's view on Crimea</p>\n            </li>\n            <li>\n               <p>\n                  <code>SDN</code>: Sudan's view on the Halaib Triangle</p>\n            </li>\n            <li>\n               <p>\n                  <code>SRB</code>: Serbia's view on Kosovo, Vukovar, and Sarengrad Islands</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUR</code>: Suriname's view on the Courantyne Headwaters and Lawa\n               Headwaters</p>\n            </li>\n            <li>\n               <p>\n                  <code>SYR</code>: Syria's view on the Golan Heights</p>\n            </li>\n            <li>\n               <p>\n                  <code>TUR</code>: Turkey's view on Cyprus and Northern Cyprus</p>\n            </li>\n            <li>\n               <p>\n                  <code>TZA</code>: Tanzania's view on Lake Malawi</p>\n            </li>\n            <li>\n               <p>\n                  <code>URY</code>: Uruguay's view on Rincon de Artigas</p>\n            </li>\n            <li>\n               <p>\n                  <code>VNM</code>: Vietnam's view on the Paracel Islands and Spratly Islands</p>\n            </li>\n         </ul>", "smithy.api#httpQuery" => "political-view"}))
    GetStaticMapRequest.add_member(:points_of_interests, Smithy::Schema::Shapes::ShapeRef.new(shape: MapFeatureMode, location_name: 'PointsOfInterests', traits: {"smithy.api#documentation" => "<p>Determines if the result image will display icons representing points of interest on the map.</p>", "smithy.api#httpQuery" => "pois"}))
    GetStaticMapRequest.add_member(:radius, Smithy::Schema::Shapes::ShapeRef.new(shape: DistanceMeters, location_name: 'Radius', traits: {"smithy.api#default" => nil, "smithy.api#documentation" => "<p>Used with center parameter, it specifies the zoom of the image where you can control it\n         on a granular level. Takes in any value <code>&gt;= 1</code>. </p>\n         <p>Example: <code>1500</code>\n         </p>\n         <note>\n            <p>Cannot be used with <code>Zoom</code>.</p>\n         </note>\n         <p>\n            <b>Unit</b>: <code>Meters</code>\n         </p>\n         <p/>", "smithy.api#httpQuery" => "radius"}))
    GetStaticMapRequest.add_member(:file_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'FileName', traits: {"smithy.api#documentation" => "<p>The map scaling parameter to size the image, icons, and labels. It follows the pattern\n         of <code>^map(@2x)?$</code>.</p>\n         <p>Example: <code>map, map@2x</code>\n         </p>", "smithy.api#httpLabel" => {}, "smithy.api#pattern" => "^map(@2x)?$", "smithy.api#required" => {}}))
